// Every rule in Summit Ready throws one of these (chapter 4).
// They all inherit from SummitException, so one catch catches them all.
class SummitException : Exception
{
    public SummitException(string message) : base(message) { }
}

// A box was left empty
class BlankFieldException : SummitException
{
    public BlankFieldException(string message) : base(message) { }
}

// The username is too short or too long
class UsernameLengthException : SummitException
{
    public UsernameLengthException(int length)
        : base(LengthMessage(length)) { }

    // "1 character" but "2 characters"
    private static string LengthMessage(int length)
    {
        string count = length + " characters.";
        if (length == 1) count = "1 character.";
        return "Your username has " + count + " It needs 3 to 12.";
    }
}

// A character that is not allowed in that box
class InvalidCharacterException : SummitException
{
    public InvalidCharacterException(char badCharacter, string field)
        : base(CharacterMessage(badCharacter, field)) { }

    // Names the character to take out (a space is "the space")
    private static string CharacterMessage(char badCharacter,
        string field)
    {
        if (field == "password")
        {
            return "Your password cannot use the " + badCharacter
                + " character.";
        }
        string name = "the " + badCharacter;
        if (badCharacter == ' ') name = "the space";
        return "Your username can only use letters and numbers. "
            + "Take out " + name + ".";
    }
}

// Somebody already has that username
class PlayerExistsException : SummitException
{
    public PlayerExistsException(string username)
        : base("The username " + username + " is already taken. "
            + "Try another one.") { }
}

// The password breaks one of the password rules
class WeakPasswordException : SummitException
{
    public WeakPasswordException(string message) : base(message) { }
}

// The two password boxes are different
class PasswordMismatchException : SummitException
{
    public PasswordMismatchException()
        : base("The two passwords are different. "
            + "Type them both again.") { }
}

// No avatar picture was clicked
class AvatarNotChosenException : SummitException
{
    public AvatarNotChosenException()
        : base("Click a picture to choose your avatar.") { }
}

// The username and password do not match a player
class LoginFailedException : SummitException
{
    public LoginFailedException()
        : base("That username and password do not match a player. "
            + "Check both and try again.") { }
}

// A grid reference that is not four numbers
class GridRefFormatException : SummitException
{
    public GridRefFormatException()
        : base("A grid reference here is four numbers, like 3127: "
            + "two from the top of the map, then two from the left "
            + "side.") { }
}

// A grid reference that is not on the map
class OffMapException : SummitException
{
    public OffMapException(string gridRef)
        : base(gridRef + " is not on this map. The numbers along the "
            + "top go from 27 to 36, and the numbers down the left "
            + "side go from 22 to 31.") { }
}

// A letter that was already tried in Whiteout
class LetterAlreadyTriedException : SummitException
{
    public LetterAlreadyTriedException(char letter)
        : base("You have already tried " + letter
            + ". Pick another letter.") { }
}

// The username: checked by rules 1, 2 and 3 as it is set
public string Username
{
    get { return username; }
    set
    {
        string name = value.Trim();
        if (name == "")
        {
            throw new BlankFieldException("Type a username.");
        }
        if (name.Length < 3 || name.Length > 12)
        {
            throw new UsernameLengthException(name.Length);
        }
        foreach (char c in name)
        {
            if (!char.IsLetterOrDigit(c))
            {
                throw new InvalidCharacterException(c, "username");
            }
        }
        username = name;
    }
}

// The password: checked by rules 5, 6, 7 and 8 as it is set
public string Password
{
    get { return password; }
    set
    {
        if (value == "")
        {
            throw new BlankFieldException("Type a password.");
        }
        if (value.Length < 6 || value.Length > 20)
        {
            throw new WeakPasswordException(
                "Your password needs 6 to 20 characters.");
        }
        bool hasLetter = false;
        bool hasNumber = false;
        foreach (char c in value)
        {
            if (char.IsLetter(c)) hasLetter = true;
            if (char.IsDigit(c)) hasNumber = true;
        }
        if (!hasLetter || !hasNumber)
        {
            throw new WeakPasswordException("Your password needs at "
                + "least one letter and one number.");
        }
        if (value.Contains("|"))
        {
            throw new InvalidCharacterException('|', "password");
        }
        password = value;
    }
}

// The avatar's file name: checked by rule 11 as it is set
public string Avatar
{
    get { return avatar; }
    set
    {
        if (value == "") throw new AvatarNotChosenException();
        avatar = value;
    }
}

// Checks the two password boxes: rules 9 and 10
public static void CheckPasswordsMatch(string first, string second)
{
    if (second == "")
    {
        throw new BlankFieldException("Type your password again.");
    }
    if (first != second) throw new PasswordMismatchException();
}

// Adds a new player to the end of players.txt: rule 4
public static void Add(Player p)
{
    if (Exists(p.Username))
    {
        throw new PlayerExistsException(p.Username);
    }
    StreamWriter writer = new StreamWriter(Files.Data("players.txt"),
        true);                                // true: add to the end
    writer.WriteLine(p.ToString());
    writer.Close();
}

